# ---- Sonraki Jin / Tang oncesi ----
ev('ETJ895', '0895-01-01', '895 (Qianning 2) — ay/gün yok (乙未 günü kaynakta ay belirtilmeden)', 'yil',
   'Tang Li Keyong’u Jin Prensi (Jin Wang) yaptı; Taiyuan merkezli Shatuo prensliği',
   'Wang Xingyu’nun yenilgisinin ardından Tang sarayı Hedong valisi Li Keyong’un unvanını Jin Prensi’ne yükseltti; Taiyuan (Jinyang) Shatuo prensliğinin merkezi oldu.',
   'Sima Guang, Zizhi tongjian, juan 260 (' + ZH + '資治通鑑/卷260; açıldı, okundu; Qianning 2 / 895 bölümü): «乙未，進李克用爵晉王，加李罕之兼侍中。»; Xin Wudai shi, juan 4 (' + ZH + '新五代史/卷04; okundu): «拜克用「忠正平難功臣」，封晉王。»',
   'Ay/gün kaynakta yok; yıl 895. Künye (ms1) f=0902-01-01 diyor: künye f 0895-01-01 olmalı (öneri). Li Keyong Hedong valisi olarak 883’ten beri Taiyuan’dadır; Tang resmî egemen kaldı — BEYANLI YAKLAŞIKLIK.')
ev('EZ907', '0907-06-01', 'Tang’ın sonu 907-06-01 (devir günü bu olay); Zhao Wang unvanının günü kaynakta yok', 'gun',
   'Wang Rong’un Zhenzhou (Chengde) yönetimi Tang sonrası Zhao Prensliği olarak sürdü',
   'Tang’ın ortadan kalkmasıyla Chengde valisi Wang Rong’un yönetimindeki Zhenzhou (Zhengding) ve çevresi Zhao Prensliği olarak kaldı; Wang Rong Liang’dan "Şangşu Ling" unvanı aldı.',
   'Xue Juzheng vd., Jiu Wudai shi, juan 54 «Wang Rong» (' + ZH + '舊五代史/卷54; açıldı, okundu): «鎔於昭宗朝賜號敦睦保定久大功臣，位至成德軍節度使、守太師、中書令、趙王，梁祖加尚書令。»',
   'Zhao Wang unvanının günü/yılı kaynakta yok; devir günü olarak Tang’ın sonu (E907 = 907-06-01) alındı — BEYANLI YAKLAŞIKLIK.')
ev('EZ921', '0921-02-11', '921 (Tianyou 18), 1. ay (ay ilk günü; ganzhi yok)', 'ay',
   'Zhang Wenli Wang Rong’u öldürüp Zhenzhou’yu ele geçirdi; Zhao Prensliği sona erdi',
   'Komutan Zhang Wenli ve Wang Deming’in askerleri Zhao Prensi Wang Rong’u öldürüp Wang ailesini kırdı; Zhang Wenli Jin Kralı Li Cunxu’dan "Zhenzhou emanet valisi" unvanı istedi. Zhenzhou fiilen asi Zhang’ın elinde, nominal olarak Jin’in vassalı oldu.',
   'Ouyang Xiu, Xin Wudai shi, juan 5 (' + ZH + '新五代史/卷05; okundu): «十八年正月，…趙將張文禮弒其君鎔，文禮來請命。二月，以文禮為鎮州兵馬留後。»; Zizhi tongjian, juan 271 (' + ZH + '資治通鑑/卷271; okundu): «張文禮遣使告亂於晉王，且奉箋勸進，因求節鉞。…遣節度判官盧質承製授文禮成德留後。»',
   'Tianyou 18 (921) 1. ay: ay ilk günü seçildi (' + TAK + '921-02-11); tam gün kaynakta yok. Künye t=0921-01-01 ise 0921-02-11’e (ya da öldürme günü bulunursa) düzeltilmeli.')
ev('EY907', '0907-06-01', 'Tang’ın sonu 907-06-01 (devir günü bu olay)', 'gun',
   'Youzhou (Lulong) Liu Shouguang’ın elinde Liang’a nominal bağlı kaldı',
   'Liu Shouguang Liang’ın kuruluş yılında babasını hapsedip Lulong valiliğini ele geçirdi; Youzhou çevresi Tang’ın çöküşünden sonra nominal Liang egemenliğinde (Hebei teftiş görevi, "Şangfu" unvan oyunları) ama fiilen bağımsız yönetildi.',
   'Xin Wudai shi, juan 39 «Liu Shouguang» (' + ZH + '新五代史/卷39; açıldı, okundu): «梁開平元年，遣李思安攻仁恭，仁恭在大安，守光自外將兵以入，擊走思安，乃自稱盧龍節度使…»; «梁遣閤門使王瞳拜守光河北採訪使。»',
   'Liang’ın nominal egemenliği BEYANLI YAKLAŞIKLIK: Liu Shouguang Liang’ın "Hebei teftiş görevlisi" unvanını aldı ama kendi dönem adını (Yingtian) sonradan kullandı; 907-06-01 Tang’ın sonu devir günü olarak alındı.')
ev('EY911', '0911-09-08', '911 (Qianhua 1), 8. ay, ganzhi 甲子 (Jülyen 911-09-08)', 'gun',
   'Liu Shouguang imparator ilan edip Yan (Büyük Yan) devletini kurdu',
   'Liu Shouguang, Jin ve Zhao’nun "Şangfu" ünvanı sunmasını aşağılayıp 911’de Youzhou’da imparator ilan etti; devlet adı Büyük Yan (Da Yan), dönem adı Yingtian. Youzhou Yan’ın başkentidir.',
   'Zizhi tongjian, juan 268 (' + ZH + '資治通鑑/卷268; açıldı, okundu): «甲子，守光即皇帝位。國號大燕，改元應天。»; Xin Wudai shi, juan 39: «守光遂以梁乾化元年八月，自號大燕皇帝，改元曰應天»',
   TAK + '911 8. ay 甲子 = 911-09-08 (Gregoryen 911-09-13); iki kaynak ay (8. ay) konusunda uyumlu, gün adı yalnız ZZTJ’de.')
ev('EY913', '0913-11-01', '913 (Tianyou 10), 10. ay (ay ilk günü); Jin’in Youzhou’yu alışı 10.–11. ay', 'ay',
   'Jin, Youzhou’yu aldı; Yan devleti yıkıldı',
   'Zhou Dewei komutasındaki Jin ordusu Youzhou’ya girdi; Liu Shouguang önce teslim olacağını söyleyip sözünden döndü, kent saldırıyla alındı. Zhou Dewei Lulong (Youzhou) valisi atandı; Yan sona erdi.',
   'Xin Wudai shi, juan 5 (' + ZH + '新五代史/卷05; okundu): «十年十月，劉守光請降，王如幽州，守光背約不降，攻破之。十一年，殺燕王劉守光于太原»; Zizhi tongjian, juan 269 (' + ZH + '資治通鑑/卷269; okundu): «庚午，晉王以周德威為盧龍節度使，兼侍中。»',
   'Tianyou 10 (913) 10. ay: ay ilk günü (' + TAK + '913-11-01); kaynak kent düşüş gününü vermiyor. Künye t=0913-01-01 yanlış görünür: 0913-11-01 (ay) olmalı (öneri).')
ev('EY1123', '1123-01-04', '1122 (Tianfu 6), 12. ay, ganzhi 庚寅 (Jülyen 1123-01-04)', 'gun',
   'Jin ordusu Yanjing’e (Pekin) girdi; Liao Güney Başkenti Jin’e geçti',
   'Wanyan Aguda’nın ordusu Juyongguan’dan geçip Yanjing’e güney kapısından girdi; Liao bakanları (Zuo Qigong, Yu Zhongwen ve ötekiler) teslim oldu. Yanjing (Liao Nanjing) Jin’in eline geçti.',
   'Tuotuo vd., Jin shi, juan 2 «Taizu ben ji» (' + ZH + '金史/卷2; açıldı, okundu): «十二月，上伐燕京。…庚寅，遼統軍都監高六等來送款。上至燕京，入自南門，…遼知樞密院左企弓、虞仲文，…奉表降。辛卯，遼百官詣軍門叩頭請罪»',
   TAK + 'Tianfu 6 (1122) 12. ay 庚寅 = 1123-01-04 (Gregoryen 1123-01-11).')
ev('ESH907', '0907-06-01', 'Tang’ın sonu 907-06-01 (devir günü); Wang Jian imparatorluk ilanı 907-11-03', 'gun',
   'Tang’ın düşüşü: Wang Jian Liang’ı reddedip Shu’da (Chengdu) bağımsız kaldı',
   'Liang Tang’ı yıkınca Wang Jian Liang’ın elçisini kabul etmedi ve Chengdu merkezli Sichuan’da bağımsız kaldı; aynı yıl (907-11-03) imparator ilan etti, Önceki Shu bu devletin resmî adıdır.',
   'Xin Wudai shi, juan 63 «Qian Shu shijia» (' + ZH + '新五代史/卷63; açıldı, okundu): «七年，梁滅唐，遣使者諭建，建拒而不納。…秋九月己亥，建乃即皇帝位。»',
   'Devir günü Tang’ın sonu olarak alındı; Wang Jian zaten 903’ten Shu Kralı (蜀王) idi (aynı kaynak: «三年八月，唐封建蜀王»). Künye f=0907-01-01 Tang’ın sonundan öncedir.')
ev('ESH925', '0925-12-08', '925 (Tongguang 3), 11. ay, ganzhi 己酉 (Jülyen 925-12-08)', 'gun',
   'Sonraki Tang Sichuan’ı fethetti; Wang Yan Chengdu’da teslim oldu, Önceki Shu sona erdi',
   'Li Jiji ve Guo Chongtao komutasındaki Tang ordusu Chengdu’ya ilerlerken Önceki Shu imparatoru Wang Yan, Qiqiqiao’da (Yedi Li Köprüsü) teslim oldu; Sichuan Sonraki Tang’a geçti.',
   'Xin Wudai shi, juan 5 (' + ZH + '新五代史/卷05; okundu): «十一月丁未，高麗遣使者來。己酉，王衍降。»; juan 63: «魏王繼岌至成都，衍君臣面縛輿櫬，出降于七里亭。»',
   TAK + 'Tongguang 3 (925) 11. ay 己酉 = 925-12-08 (Gregoryen 925-12-13). Künye t=0925-01-01 ise 0925-12-08 olmalı.')
ev('EWY907', '0907-06-01', '907 (Kaiping 1), Liang’ın kuruluşu (Jülyen 907-06-01); unvan günü kaynakta yok', 'gun',
   'Liang Qian Liu’ya Wuyue Kralı unvanı verdi; Hangzhou Wuyue’nin merkezi',
   'Liang kurulunca Zhenhai–Zhendong valisi Qian Liu Wuyue Kralı (吳越王) ve Huainan valisi oldu; Hangzhou merkezli Wuyue Krallığı Tang sonrası bağımsız bir krallık olarak sürdü.',
   'Xin Wudai shi, juan 67 «Wuyue shijia» (' + ZH + '新五代史/卷67; açıldı, okundu): «梁太祖即位，封鏐吳越王兼淮南節度使。客有勸鏐拒梁命者，鏐笑曰：「吾豈失為孫仲謀邪！」遂受之。»',
   'Unvanın günü kaynakta yok; Liang’ın kuruluş günü (907-06-01) devir günü olarak alındı. Kaynak aynı sayfada «自唐乾寧二年為鎮海、鎮東軍節度使兼有兩浙，至皇朝太平興國三年國除，凡八十四年» der: Qian Liu’nun fiilî egemenliği 895’ten.')
ev('EWY978', '0978-01-01', '978 (Taiping Xingguo 3) — ay/gün yok', 'yil',
   'Qian Chu Wuyue’yu Song’a bağladı; Hangzhou ve iki Zhejiang Song’a geçti',
   'Song imparatoru Qian Chu’yu başkente çağırdı; Qian Chu bütün ailesiyle Song başkentine gidip ülkesini bağladı. Wuyue Krallığı kaldırıldı, Hangzhou Song’a geçti.',
   'Xin Wudai shi, juan 67 (' + ZH + '新五代史/卷67; okundu): «太平興國三年，詔俶來朝，俶舉族歸于京師，國除。»',
   'Ay/gün kaynakta yok: YYYY-01-01 kuralı; gerçek devir 978’in ilerleyen ayları (Song tarafı kaynakları okunmadı).')
ev('EYW902', '0902-01-01', '902 (Tianfu 2) — ay/gün yok', 'yil',
   'Tang Yang Xingmi’ye Wu Kralı unvanı verdi; Yangzhou merkezli Yang Wu',
   'Tang imparatoru Zhaozong Yang Xingmi’yi Doğu Yönü Komutanı ve Wu Kralı (吳王) yaptı; Huainan’ın merkezi Yangzhou Wu devletinin başkenti oldu.',
   'Xin Wudai shi, juan 61 «Wu shijia» (' + ZH + '新五代史/卷61; açıldı, okundu): «是歲，唐昭宗在岐，遣江淮宣諭使李儼拜行密東面諸道行營都統、檢校太師、中書令，封吳王。»',
   'Tianfu 2 = 902 (aynı sayfada «天復二年» ile bağlı); ay/gün kaynakta yok.')
ev('EYW937', '0937-10-01', '937 (Tianzuo 3), 10. ay (ay ilk günü; Jülyen 937-11-06 — künye t=0937-10-01)', 'ay',
   'Yang Pu tahtı Xu Zhigao’ya devretti; Wu sona erdi, Yangzhou Güney Tang’a geçti',
   'Wu imparatoru Yang Pu, Jiangxia Prensi Yang Lin’i göndererek tahtı Qi Kralı Xu Zhigao’ya (Li Bian) devretti; Wu yerini Güney Tang’a bıraktı. Yangzhou Wu’nun Doğu Başkenti, Jinling Batı Başkenti idi.',
   'Xin Wudai shi, juan 61 (' + ZH + '新五代史/卷61; okundu): «三年，知誥建齊國，立宗廟、社稷，置左、右丞相已下，以金陵為西都，廣陵為東都。冬十月，溥遣江夏王璘奉冊禪位於齊王。»',
   'Tianzuo 3 (937) 10. ay: ay ilk günü seçildi (' + TAK + '937-11-06); künye t=0937-10-01 ile 36 gün fark → künye t=0937-11-06 olmalı (öneri).')
ev('EMN907', '0907-06-01', '907 (Kaiping 1), Liang’ın kuruluşu (Jülyen 907-06-01); unvan günü kaynakta yok', 'gun',
   'Liang Wang Shenzhi’ye Min Kralı unvanı verdi; Fuzhou Min’in merkezi',
   'Tang’ın çöküşünde Liang Fujian valisi Wang Shenzhi’ye "Zhongshu Ling" ve Min Kralı (閩王) unvanını verdi; Fuzhou Büyük Valilik (Dadudufu) yapıldı.',
   'Xin Wudai shi, juan 68 «Min shijia» (' + ZH + '新五代史/卷68; açıldı, okundu): «唐亡，梁太祖加拜審知中書令，封閩王，升福州為大都督府。»',
   'Unvanın günü kaynakta yok; 907-06-01 devir günü olarak alındı. Künye f=0909-01-01 ise 0907-06-01 olmalı (öneri; Min kaynağı «唐亡» diyor).')
ev('EMN945', '0945-01-01', '945/946 — kaynaklar çelişir (Xin Wudai 946, Jiangnan lu 945) — ay/gün yok', 'yil',
   'Güney Tang Min’i yıktı; Fuzhou Güney Tang’a geçti',
   'Güney Tang ordusu Jianzhou’yu aldı ve Wang ailesinin Min devletine son verdi; Fuzhou Güney Tang’ın eline geçti.',
   'Xin Wudai shi, juan 68 (' + ZH + '新五代史/卷68; okundu): «〈晉開運三年丙午，南唐保大四年也。是歲，李景兵破建州，王氏滅。江南錄云：「保大三年，虜王氏之族，遷于金陵。」謬也。〉»',
   'ÇELİŞKİ: Xin Wudai 946 (Kaiyun 3 = Baoda 4), Jiangnan lu 945 (Baoda 3); Xin Wudai ikincisini "yanlış" der, yani 946. Künye t=0945-01-01. Seçim: künye (945) korundu; Fuzhou’nun fiilî Güney Tang’a geçişi Jianzhou’nun düşüşünden sonradır.')
ev('EGZ907', '0907-06-01', '907 (Kaiping 1), Liang’ın kuruluşu (Jülyen 907-06-01); Liu Yin’in unvanı «梁開平元年…加檢校太尉、兼侍中»', 'gun',
   'Guangzhou’daki Liu Yin Liang’dan unvan aldı; Lingnan nominal Liang egemenliğinde',
   'Qinghai valisi Liu Yin Liang’ın kuruluşunda Liang’dan "Taiwei" ve "Shizhong" unvanları aldı; Liu Yin ve kardeşi Liu Yan "Liang’ın başlangıcından beri unvan alıp Liang takvimini kullandı". Guangzhou fiilen kendi valilerince yönetildi.',
   'Xin Wudai shi, juan 65 «Nan Han shijia» (' + ZH + '新五代史/卷65; açıldı, okundu): «天祐二年，拜隱節度使。梁開平元年，加檢校太尉、兼侍中。二年，兼靜海軍節度、安南都護。三年，加檢校太師、兼中書令，封南平王。»; «隱、龑自梁初受封爵，禀正朔而已。»',
   'Nominal egemenlik: BEYANLI YAKLAŞIKLIK — Liu Yin/Yan Liang’dan unvan aldı ve "正朔" (takvim) kullandı (aynı kaynak); Tang’ın sonu devir günü olarak alındı.')
ev('EGZ917', '0917-01-01', '917 (Zhenming 3) — ay/gün yok', 'yil',
   'Liu Yan imparator ilan etti: Büyük Yue (sonra Han); Guangzhou Güney Han’ın başkenti',
   'Liu Yan Guangzhou’da (Xingwangfu) imparatorluğunu ilan etti, devlet adı Büyük Yue (Da Yue), dönem adı Qianheng; Guangzhou Güney Han’ın merkezi oldu.',
   'Xin Wudai shi, juan 65 (' + ZH + '新五代史/卷65; okundu): «貞明三年，龑即皇帝位，國號大越，改元曰乾亨。追尊安仁文皇帝，謙聖武皇帝，隱襄皇帝，立三廟。»',
   'Zhenming 3 = 917; ay/gün kaynakta yok.')
ev('EGZ971', '0971-02-28', '971 (Kaibao 4), 2. ay (ay ilk günü; Jülyen 971-02-28)', 'ay',
   'Song ordusu Guangzhou’ya girdi; Liu Chang teslim oldu, Güney Han yıkıldı',
   'Pan Mei komutasındaki Song ordusu Maqi’de Güney Han savunmasını kırdı; Liu Chang önce elçi gönderdi, sonra savunma düzenlemeye kalktı ve saray-hazineyi yaktırdı; Song’a teslim oldu. Güney Han kaldırıldı.',
   'Xin Wudai shi, juan 65 (' + ZH + '新五代史/卷65; okundu): «開寶四年正月，平英、雄二州，…二月，師度馬逕，鋹遣其右僕射蕭漼奉表降。…乃盡焚其府庫、宮殿。…師次白田，鋹素衣白馬以降。»',
   'Kaibao 4 (971) 2. ay: ay ilk günü seçildi (' + TAK + '971-02-28); kentin düşüş günü kaynakta yok. DEVLET_LISTESI künye t=0971-02-01 → 0971-02-28 (ay ilk günü, takvim çevrimi) olmalı.')
ev('ECM907', '0907-06-01', '907 (Kaiping 1), Liang’ın kuruluşu (Jülyen 907-06-01); unvan günü kaynakta yok', 'gun',
   'Liang Ma Yin’e Chu Kralı unvanı verdi; Tanzhou (Changsha) Chu’nun merkezi',
   'Tang’ın çöküşünde Liang, Wu’an valisi Ma Yin’e "Shizhong–Zhongshu Ling" ve Chu Kralı (楚王) unvanını verdi; Tanzhou (Changsha) Chu’nun merkezi olarak kaldı.',
   'Xin Wudai shi, juan 66 «Chu shijia» (' + ZH + '新五代史/卷66; açıldı, okundu): «梁太祖即位，殷遣使脩貢，太祖拜殷侍中兼中書令，封楚王。»; «唐拜殷潭州刺史…時乾寧三年也。»',
   'Unvanın günü kaynakta yok; 907-06-01 devir günü. Künye f=0927-01-01 (Tianqing 2, Mingzong: «天成二年…封殷楚國王») Chu’nun 907 egemenliğini kapsamaz: künye f 0907-06-01 olmalı (öneri; Changsha 907–927 yoksa sahipsiz kalır).')
ev('ECM951', '0951-01-01', '951 (Guangshun 1) — ay/gün yok', 'yil',
   'Güney Tang Chu’yu yıktı; Changsha Güney Tang’ın eline geçti',
   'Ma ailesinin kardeş kavgasında Ma Xi’e Güney Tang’a bağlandı, Güney Tang ordusu Chu’yu ele geçirdi ve Ma ailesi Jinling’e götürüldü.',
   'Xin Wudai shi, juan 66 (' + ZH + '新五代史/卷66; okundu): «〈殷自唐乾寧三年入湖南，至周廣順元年，凡五十七年，餘具年譜注。〉»; «希萼遂臣於李景，景冊封希萼楚王»',
   'Guangshun 1 = 951; ay/gün kaynakta yok. Changsha’nın Güney Tang’dan sonraki zinciri (Wuping vd.) bu kümede yok.')
ev('ENP907', '0907-06-01', '907 (Kaiping 1), Liang’ın kuruluşu (Jülyen 907-06-01); Gao Jixing’in valiliği «開平元年…拜季興節度使»', 'gun',
   'Liang Gao Jixing’i Jingnan valisi atadı; Jiangling (Jingzhou) nominal Liang egemenliğinde',
   'Liang, Xiangyang’ın Jingnan’daki işgalcisi Zhao Kuangming’i sürünce Gao Jixing’i Jingnan valisi yaptı; Jiangling o sırada "yalnız tek kent" idi. Jingnan Liang’ın vassalı sayıldı (haraç kesintileriyle).',
   'Xin Wudai shi, juan 69 «Jingnan shijia» (' + ZH + '新五代史/卷69; açıldı, okundu): «梁兵攻破襄州，匡凝奔于吳，匡明奔于蜀，乃以季興為荊南節度觀察留後。開平元年，拜季興節度使。荊南節度十州，當唐之末，為諸道所侵，季興始至，江陵一城而已。»',
   '"自梁開平元年鎮荊南，至皇朝乾德元年國除，凡五十七年" (aynı kaynak). Nominal Liang egemenliği BEYANLI YAKLAŞIKLIK; 907-06-01 devir günü.')
ev('ENP924', '0924-01-01', '924 (Tongguang 2) — Jingnan’ın Tang’a bağlanışı: 924 başı (künye f)', 'yil',
   'Gao Jixing Sonraki Tang’a bağlandı; Jingnan künye başlangıcı',
   'Liang’ın yıkılışından sonra Gao Jixing Luoyang’a gidip Zhuangzong’a bağlandı; Tang ona Nanping Kralı (南平王) unvanını verdi (925). Jingzhou Nanping/Jingnan’ın merkezi.',
   'Xin Wudai shi, juan 69 (' + ZH + '新五代史/卷69; okundu): «梁亡，唐莊宗入洛，下詔慰諭季興，…季興…朝于洛陽。…同光三年，封南平王。»',
   'Yıl: künye f=0924-01-01; kaynaktaki "同光三年封南平王" = 925. Nanping unvanı 925; dilim sınırı künyeyi izledi (BEYANLI).')
ev('ENP963', '0963-01-01', '963 (Jianlong 4 = Qiande 1) — Song ordusunun Jingzhou’ya girişi (ay yok)', 'yil',
   'Song ordusu Jingzhou’ya girdi; Gao Jichong teslim oldu, Nanping kaldırıldı',
   'Song ordusu Hunan seferi için "kent dışından geçiş" sözüyle Jiangling’e vardı; öncü birlikler kente girdi, Gao Jichong valilik mührünü teslim etti. Aynı yıl 9. ayda ailesiyle başkente gitti; Nanping kaldırıldı.',
   'Xin Wudai shi, juan 69 (' + ZH + '新五代史/卷69; okundu): «建隆四年，太袓命慕容延釗等討之。延釗假道荊南，約以兵過城外。…前鋒遽入其城。繼冲…即詣延釗納牌印，…乾德元年，…九月，…率其將吏、宗族五百餘人朝于京師»',
   'Jianlong 4 (963) = Qiande 1; ay/gün yok, YYYY-01-01 kuralı (devir 963’ün ilk yarısı).')
ev('EDC902', '0902-01-01', '902 — ay/gün yok', 'yil',
   'Zheng Maisi Nanzhao’daki Meng hanedanını devirdi: Büyük Changhe (Da Changhe)',
   'Zheng Maisi, Meng ailesinin yönetimini sona erdirip Nanzhao’nun ikinci hanedanını kurdu ve ülke adını Da Changhe koydu. Yangjumie/Dali yöresi Da Changhe’nin merkezi oldu.',
   'Ulrich Theobald, «Nanzhao 南詔» (chinaknowledge.de/History/Altera/nanzhao.html; açıldı, okundu; kaynakça: Bryson 2015, Cahiers d’Extrême-Asie 24): «In 902 Zheng Maisi 鄭買嗣, a descendant of Zheng Hui, usurped the throne and ended the rule of the Meng family of Nanzhao. … changed the name of the country to Da Changhe 大長和.»',
   'Aynı kaynak tablo 2’de Zheng Maisi saltanatını 903–909 verir (902 darbe, 903 saltanat başı). Ayrıntılı birincil kaynak bulunamadı (Xin Tang shu 222, ZZTJ 263–265, Song shi 488, Xin Wudai 74 tarandı: Zheng Maisi geçmiyor).')
ev('EDC928', '0928-01-01', '927/928 — ay/gün yok', 'yil',
   'Zheng ailesi devrildi; Da Tianxing (Zhao Shanzheng) kuruldu',
   'Da Changhe 927’de Zheng ailesinin sonuyla yıkıldı; 928’de Zhao Shanzheng Da Tianxing devletini kurdu (Yang Ganzhen’in desteğiyle). Dali yöresi Da Tianxing’e geçti.',
   'Theobald, chinaknowledge.de «Nanzhao» (okundu): «The Zheng family ruled until 927 and was then replaced by 趙善政 (r. 928-929), ruler of Da Tianxing 大天興, who was again followed by Yang Ganzhen 楊干真 (r. 930-937)…»',
   'ÇELİŞKİ: aynı kaynak tabloda Da Changhe için 903–927, Da Tianxing için 928–929; başka derlemeler (Vikipedi aynası) 927/928 farkını ve Yang Ganzhen’in rolünü farklı verir. Seçim: künye t=0928-01-01 (girdi) korundu.')
ev('EXD881', '0881-01-01', '881 (Zhonghe 1) — ay/gün yok', 'yil',
   'Tuoba Sigong Xiazhou’nun (Dingnan Jun) emanet valisi oldu',
   'Huang Chao isyanına karşı Tang’ın yanında savaşan Dangxiang (Tangut) reisi Tuoba Sigong Xiazhou’nun (Tongwan Şehri) vekil valisi oldu; sonra Dingnan Jun valisi ve Li soyadı sahibi. Xiazhou Dangxiang yönetiminin merkezi.',
   'Sima Guang, Zizhi tongjian, juan 254 (' + ZH + '資治通鑑/卷254; açıldı, okundu; Zhonghe 1 / 881 bölümü): «鄜延節度使李孝昌、權夏州節度使拓跋思恭屯東渭橋，黃巢遣朱溫拒之。»; Song shi 485 (' + ZH + '宋史/卷485; okundu): «唐末，拓跋思恭鎮夏州，統銀、夏、綏、宥、靜五州地，討黃巢有功，復賜李姓。»',
   'Yıl 881 (ZZTJ 254 Zhonghe 1: "權夏州節度使"); tam vali atanışı ZZTJ’de 882 bölümünde olabilir (okunmadı). Künye f=0881-01-01 ile uyumlu.')
ev('EXZ982', '0982-01-01', '982 (Taiping Xingguo 7) — ay/gün yok', 'yil',
   'Li Jipeng Xiazhou’yu Song’a bıraktı: Dingnan Jun Song’un doğrudan idaresine girdi',
   'Dangxiang yöneticisi Li Jipeng akrabalarıyla Song başkentine gelip Yin–Xia bölgesindeki yönetimi bıraktı; Song Xiazhou’ya doğrudan vali (zhi Xiazhou) atadı. Li Jiqian ayaklanmaya başladı.',
   'Song shi, juan 485 (' + ZH + '宋史/卷485; okundu): «繼捧立，以太平興國七年率族人入朝。…遂曲赦銀、夏管內。»; «太平興國八年，知夏州尹憲與都巡檢曹光實偵知，夜襲破之»',
   'Taiping Xingguo 7 = 982; ay/gün yok.')
ev('EXZ988', '0988-01-01', '988 (Duangong başı) — ay/gün yok', 'yil',
   'Song Li Jipeng’i (Zhao Baozhong) Xiazhou’ya Dingnan valisi olarak geri gönderdi',
   'Song, Li Jiqian’a karşı kullanmak üzere Li Jipeng’e Zhao soyadı verip (Zhao Baozhong) Xiazhou prefekti ve Dingnan Jun valisi yaparak geri gönderdi.',
   'Song shi, juan 485 (okundu): «端拱初，…召赴闕，賜姓趙氏，更名保忠，…授夏州刺史，充定難軍節度使、夏銀綏宥靜等州觀察處置押蕃落等使»',
   'Duangong başı = 988 (Duangong 1 = 988); ay/gün yok.')
ev('EXD1028', '1028-01-01', '1028 (Tiansheng 6) — ay/gün yok', 'yil',
   'Li Yuanhao Ganzhou’yu (Zhangye) Uygurlardan aldı',
   'Li Deming’in oğlu Li Yuanhao Ganzhou Uygur Kağanlığı’nın başkenti Ganzhou’yu (Zhangye) alıp Dingnan Jun yönetimine kattı; Hexi koridoru Dangxiang’a geçmeye başladı.',
   'Song shi, juan 485 (' + ZH + '宋史/卷485; okundu): «天聖六年，德明遣子元昊攻甘州，拔之。»',
   'Tiansheng 6 = 1028; ay/gün yok. Künye t=1036-01-01: Ganzhou Uygur Krallığı’nın kendisi Ganzhou 1028’de düşünce sona ermiş sayılmalı (künye t 1028 olmalı; Gua-Sha-Su 1035/36 ayrı).')
ev('EXD1038', '1038-01-01', '1038 (Baoyuan 1) — ay/gün yok (künye t/f=1038-01-01)', 'yil',
   'Li Yuanhao imparator ilan etti: Büyük Xia (Batı Xia) kuruldu',
   'Li Yuanhao altar kurdurup imparator ilan etti, devlet adını Büyük Xia koydu; Xiazhou Dangxiang yönetimi Batı Xia devletine dönüştü, Hexi (Ganzhou, Shazhou) Batı Xia’nın bir parçası oldu.',
   'Song shi, juan 485 (okundu): «宋寶元元年，…遂築壇受冊，即皇帝位，時年三十。»; «元昊既悉有夏、銀、綏、宥、靜、靈、鹽、會、勝、甘、涼、瓜、沙、肅»',
   'Baoyuan 1 = 1038; kaynak ay vermiyor (Song shi 485’te «築壇受冊»).')
ev('EG851', '0851-01-01', '851 (Dazhong 5) — ay/gün yok (künye f/DEVLET_LISTESI düzeltme: 0851-01-01)', 'yil',
   'Zhang Yichao Shazhou’yu Tang’a bağladı: Guiyi Jun kuruldu',
   'Shazhou’nun (Dunhuang) Tibet egemenliğinden kurtarıcısı Zhang Yichao eyaletle Tang’a bağlılığını bildirdi; Tang Shazhou’yu Guiyi Jun (Dönüş-Adalet Valiliği) yapıp Zhang Yichao’yu vali atadı.',
   'Song shi, juan 490 «Waiguo 6: Shazhou» (' + ZH + '宋史/卷490; açıldı, okundu): «沙州本漢燉煌故地，唐天寶末陷于西戎。大中五年，張義潮以州歸順，詔建沙州為歸義軍，以義潮為節度使，領河沙甘肅伊西等州觀察、營田處置使。»',
   'Dazhong 5 = 851 (Song shi). Künye (devletler.js) f=0848-01-01 Zhang Yichao’nun Shazhou’yu alışını (848; bu kaynakta yok) verir: seçim 851 = Tang tanıması; Dunhuang’ın Tibet’ten geçişi 848’de olmuş olabilir (cin1 Tubo dilimi sınırı).')
ev('EG1036', '1036-01-01', '1035/1036 — kaynaklar çelişir (Song shi 485: Jingyou 2 = 1035) — ay yok', 'yil',
   'Li Yuanhao Gua, Sha ve Su eyaletlerini aldı: Guiyi Jun sona erdi',
   'Li Yuanhao Qinghai yönünde Tibetli Gusiluo’ya yönelirken Guazhou, Shazhou (Dunhuang) ve Suzhou’yu alıp Guiyi Jun’a son verdi; Shazhou Dangxiang yönetimine geçti.',
   'Song shi, juan 485 (okundu; Jingyou 2 bölümü): «又攻青唐、安二、宗哥、帶星嶺諸城，…遂取瓜、沙、肅三州。»',
   'ÇELİŞKİ: Song shi 485 anlatıda bu fethi Jingyou 2 (1035) altında anar; künye t=1036-01-01 (Xu zizhi tongjian changbian 1036 verir, okunmadı). Seçim: künye (1036).')
ev('ELY919', '0919-04-01', '919 (Shence 4), 2. ay, ganzhi 丙寅 (Jülyen 919-04-01)', 'gun',
   'Liao Liaoyang’ı onarıp Dongping Komutanlığı (Liaoyang) yaptı',
   'Abaoji Liaoyang’ın eski surlu kentini onarıp Han ve Bohai hanelerini yerleştirdi, adını Dongping Komutanlığı yaptı ve bir savunma valisi atadı. Liaoyang Liao’nun Doğu Bölgesi’nin merkezi olarak yükseldi (928 Nanjing, 938 Dongjing).',
   'Tuotuo vd., Liao shi, juan 2 «Taizu xia» (' + ZH + '遼史/卷2; açıldı, okundu): «二月丙寅，修遼陽故城，以漢民、渤海戶實之，改為東平郡，置防禦使。»',
   TAK + 'Shence 4 2. ay 丙寅 = 919-04-01 (Gregoryen 919-04-06). Liaoyang’ın 919 öncesi sahibi bu kümede yok (Bohai/harap).')
ev('ELY1116', '1116-06-12', '1116 (Shouguo 2), 5. ay (ay ilk günü; Jülyen 1116-06-12)', 'ay',
   'Jin Liaoyang’ı (Liao Dongjing) aldı; Gao Yongchang ayaklanması bastırıldı',
   'Liao Dongjing’de (Liaoyang) ayaklanan Gao Yongchang Jin’den yardım istedi; Wanyan Wolu komutasındaki Jin ordusu Yongchang’ı yenip yakaladı, Dongjing ve çevre Jin’e geçti. Liao Liaoyang’ı kaybetti.',
   'Jin shi, juan 2 «Taizu ben ji» (' + ZH + '金史/卷2; açıldı, okundu): «閏月，高永昌據東京，使撻不野來求援。…五月，斡魯等敗永昌，撻不野擒永昌以獻，戮之于軍。東京州縣及南路系遼女直皆降。»',
   'Shouguo 2 (1116) 5. ay: ay ilk günü (' + TAK + '1116-06-12); gün yok. Gao Yongchang’ın kısa "Büyük Yuan" rejimi (Şubat–Haziran 1116) Liao’ya yazıldı — BEYANLI YAKLAŞIKLIK.')
ev('E936LI', '0936-11-28', '936, 11. ay, ganzhi 丁酉 (Jülyen 936-11-28)', 'gun',
   'Sonraki Jin On Altı Vilayet’i (Youzhou/Pekin ve Yunzhou/Datong dahil) Kitan’a bıraktı',
   'Shi Jingtang’ın kuruluş bildirisiyle Youzhou, Jizhou, Yingzhou, Moxian, Zhuozhou, Tanzhou, Shunzhou, Xinzhou, Guizhou, Ruzhou, Wuzhou, Weizhou, Yingzhou, Shuozhou, Yunzhou ve Huanzhou Kitan’a bırakıldı. Youzhou Liao’nun Güney Başkenti (938’den) oldu.',
   Q_WD8, TAK + '11. ay 丁酉 = 936-11-28. Bildiri (936-11-28) devri başlatır; harita-belge teslimi Liao shi 4’e göre 938-11 (bkz. kronoloji). Devir günü Xin Wudai’yi izledi (BEYANLI: fiilî teslim 936–938 arası).')
ev('EBH926', '0926-02-28', '926 (Tianxian 1), 1. ay, ganzhi 辛未 (Jülyen 926-02-28)', 'gun',
   'Balhae son kralı Yi Zhen Hulhan’da Liao’ya teslim oldu',
   'Abaoji’nin ordusu Hulhan (Shangjing, Longquanfu) kentini kuşattı; Balhae kralı Da Yinzhuan (Kor. Dae Inseon) önce 己巳’de teslim olmak istedi, 辛未’de beyaz giysiyle kenti teslim etti. Balhae Krallığı sona erdi.',
   'Tuotuo vd., Liao shi, juan 2 (' + ZH + '遼史/卷2; açıldı, okundu): «夜圍忽汗城。己巳，諲譔請降。庚午，駐軍於忽汗城南。辛未，諲譔素服，稿索牽羊，率僚屬三百餘人出降。»',
   TAK + 'Tianxian 1 1. ay (Liao takvimi 926-02-15’te başlar; 4. ay 丁亥朔 = 926-05-15 çapası): 己巳 = 926-02-26, 辛未 = 926-02-28 (Gregoryen 926-03-05). Astronomik tabloda bu ay "artık 1. ay" çıkar; çapa Liao shi’nin 丁亥朔’ı.')
ev('EDD926', '0926-04-04', '926 (Tianxian 1), 1./2. ay, ganzhi 丙午 (Jülyen 926-04-04)', 'gun',
   'Liao Balhae’yi Dongdan adıyla vasal krallığa çevirdi; Hulhan Tianfu oldu',
   'Abaoji Balhae devletinin adını Dongdan (Doğu Dan) yaptı, Hulhan kentine Tianfu adını verdi ve veliaht Yelü Bei’yi "İnsan Kral" (Renhuang Wang) olarak başına geçirdi.',
   'Liao shi, juan 2 (okundu): «丙午，改渤海國為東丹，忽汗城為天福。冊皇太子倍為人皇王以主之。»',
   TAK + '丙午 = 926-04-04 (Gregoryen 926-04-09); DEVLET_LISTESI de 4 Nisan 926 verir (bağımsız çevrim). Balhae’nin 辛未 teslimi ile 丙午 arası 35 gün Liao askerî işgalidir (BEYANLI: liao-hanedani).')
